INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20UGWHQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'The values $3$, $5$, $12$, $18$, $22$, and $x$ form a data set where $x > 22$. If the mean of the data set equals the median, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '30', ARRAY['30'], E'Since $x > 22$, the sorted data set is $3, 5, 12, 18, 22, x$. With $6$ values, the median is the average of the $3$rd and $4$th values: $\\frac{12 + 18}{2} = 15$. The mean is $\\frac{3 + 5 + 12 + 18 + 22 + x}{6} = \\frac{60 + x}{6}$. Setting the mean equal to the median: $\\frac{60 + x}{6} = 15$, so $60 + x = 90$ and $x = 30$. A common error is using the $3$rd and $4$th values of the unsorted list rather than the sorted list, which would give a different median. Another error is forgetting to include $x$ in the sum when computing the mean.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2174AC0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A population of $2{,}000$ increases by $20\\%$ during the first year and then decreases by $10\\%$ during the second year. What is the population at the end of the second year?', NULL, $lyceon_json$[{"key":"A","text":"$1{,}800$"},{"key":"B","text":"$2{,}160$"},{"key":"C","text":"$2{,}200$"},{"key":"D","text":"$2{,}400$"}]$lyceon_json$::jsonb, 'B', NULL, E'After the first year, the population is $2{,}000 \\times 1.20 = 2{,}400$. After the second year, it decreases by $10\\%$: $2{,}400 \\times 0.90 = 2{,}160$. The value $1{,}800$ results from applying the $10\\%$ decrease to the original $2{,}000$ first and ignoring the order of operations. The value $2{,}200$ comes from treating the net change as a simple $+20\\% - 10\\% = +10\\%$ applied to the original population, which incorrectly assumes the percentages apply to the same base. The value $2{,}400$ results from computing only the first year''s increase without applying the second year''s decrease.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22BVLP7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains $3$ red marbles, $5$ blue marbles, and $2$ green marbles. If one marble is selected at random, what is the probability of selecting a blue marble?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1}{5}$"},{"key":"B","text":"$\\frac{1}{3}$"},{"key":"C","text":"$\\frac{1}{2}$"},{"key":"D","text":"$\\frac{3}{5}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The total number of marbles is $3 + 5 + 2 = 10$. The probability of selecting a blue marble is $\\frac{5}{10} = \\frac{1}{2}$. The value $\\frac{1}{5}$ results from incorrectly using $5$ as both numerator and denominator in a fraction. The value $\\frac{1}{3}$ comes from assuming each color is equally likely, dividing $1$ by the number of colors. The value $\\frac{3}{5}$ results from a computational error when simplifying the fraction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22DPC2P', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $g(x) = (x - 3)^2 + 5$ has a minimum value. What is that minimum value?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$8$"},{"key":"D","text":"$-5$"}]$lyceon_json$::jsonb, 'B', NULL, E'The function is in vertex form $g(x) = (x - h)^2 + k$, where the vertex is at $(h, k) = (3, 5)$. Since the coefficient of $(x - 3)^2$ is positive, the parabola opens upward and the minimum value of $g(x)$ is $5$. The value $3$ is the $x$-coordinate of the vertex, not the minimum output value. The value $8$ incorrectly adds the vertex coordinates $3 + 5$. The value $-5$ applies a sign error to the constant term in the vertex form.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23ARKBH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular garden has a length of $12$ feet and a width of $5$ feet. What is the area of the garden, in square feet?', NULL, $lyceon_json$[{"key":"A","text":"$34$"},{"key":"B","text":"$60$"},{"key":"C","text":"$17$"},{"key":"D","text":"$120$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a rectangle is length times width: $12 \\times 5 = 60$ square feet. The answer $34$ results from computing the perimeter ($2(12 + 5) = 34$) instead of the area, confusing the two formulas. The answer $17$ comes from adding the length and width rather than multiplying. The answer $120$ results from an incorrect doubling of the area.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
