INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM245YMFU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'In a survey of $200$ students, $80$ play a sport, $60$ play a musical instrument, and $30$ play both a sport and a musical instrument. What is the probability that a randomly selected student plays a sport or a musical instrument?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{3}{20}$"},{"key":"B","text":"$\\frac{1}{2}$"},{"key":"C","text":"$\\frac{11}{20}$"},{"key":"D","text":"$\\frac{7}{10}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Using the inclusion-exclusion principle, the number of students who play a sport or a musical instrument is $80 + 60 - 30 = 110$. The probability is $\\frac{110}{200} = \\frac{11}{20}$. The value $\\frac{3}{20}$ comes from using only the $30$ students who play both, giving $\\frac{30}{200}$, which answers a different question. The value $\\frac{1}{2}$ results from an error in the subtraction step of the inclusion-exclusion formula. The value $\\frac{7}{10}$ comes from adding $80 + 60 = 140$ without subtracting the $30$ students counted in both groups, giving $\\frac{140}{200}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM247OXZ3', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'A right triangle has legs of length $6$ and $8$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$10$"},{"key":"C","text":"$14$"},{"key":"D","text":"$48$"}]$lyceon_json$::jsonb, 'B', NULL, E'Using the Pythagorean theorem: $c = \\sqrt{6^2 + 8^2} = \\sqrt{36 + 64} = \\sqrt{100} = 10$. The answer $14$ comes from adding the two legs instead of using the Pythagorean theorem. The answer $7$ results from an arithmetic error in evaluating the square root. The answer $48$ comes from multiplying the legs rather than applying the Pythagorean theorem.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24R8B15', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A company claims that its tutoring program improves SAT scores based on a study in which $300$ students who voluntarily enrolled in the program scored an average of $80$ points higher than $300$ students who did not enroll. A statistician notes that students who enrolled had higher GPAs on average than those who did not. Which of the following best explains why the company''s causal claim may not be valid?', NULL, $lyceon_json$[{"key":"A","text":"The sample size of $300$ students per group is too small to detect a meaningful difference."},{"key":"B","text":"The margin of error for the $80$-point difference was not reported."},{"key":"C","text":"Students were not randomly assigned to groups, so the difference in GPAs is a confounding variable that could account for the higher scores."},{"key":"D","text":"The study should have used a larger margin of error to account for the GPA difference."}]$lyceon_json$::jsonb, 'C', NULL, E'Because students voluntarily chose whether to enroll, this is an observational study rather than a randomized experiment. The higher average GPA among enrollees is a confounding variable: students with higher GPAs may have scored higher on the SAT regardless of the tutoring program, making it impossible to attribute the $80$-point difference solely to the program. A sample size of $300$ per group is generally adequate for detecting such a difference, so sample size is not the primary concern. While reporting the margin of error is good practice, the absence of a margin of error is not the reason the causal claim fails; the fundamental issue is the lack of random assignment. Adjusting the margin of error does not address the confounding introduced by self-selection into the program.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24VY4JD', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A shirt originally costs $\\$40$. It is on sale for $25\\%$ off. What is the sale price of the shirt?', NULL, $lyceon_json$[{"key":"A","text":"$\\$10$"},{"key":"B","text":"$\\$15$"},{"key":"C","text":"$\\$30$"},{"key":"D","text":"$\\$50$"}]$lyceon_json$::jsonb, 'C', NULL, E'The discount amount is $25\\%$ of $\\$40$: $0.25 \\times 40 = \\$10$. The sale price is $\\$40 - \\$10 = \\$30$. The value $\\$10$ is only the discount itself, not the sale price. The value $\\$15$ results from a calculation error when finding $25\\%$ of $40$. The value $\\$50$ comes from adding $25\\%$ to the original price instead of subtracting it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM254NAH0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A recipe calls for $2$ cups of flour to make $16$ cookies. How many cups of flour are needed to make $40$ cookies?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$5$"},{"key":"C","text":"$8$"},{"key":"D","text":"$20$"}]$lyceon_json$::jsonb, 'B', NULL, E'The ratio of flour to cookies is $\\frac{2}{16} = \\frac{1}{8}$, meaning $\\frac{1}{8}$ cup of flour is needed per cookie. For $40$ cookies: $40 \\times \\frac{1}{8} = 5$ cups. The value $4$ results from a computational error when scaling the proportion. The value $8$ comes from simply doubling the original flour amount without accounting for the full ratio. The value $20$ results from dividing $40$ by $2$ rather than setting up the proportion correctly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26JR7DS', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The linear function $g$ is defined for all real numbers. The table below shows selected values of $g(x)$.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26YG0FV', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'A circle has a radius of $8$. A central angle intercepts an arc of length $6\\pi$. What is the area of the sector formed by this central angle?', NULL, $lyceon_json$[{"key":"A","text":"$24\\pi$"},{"key":"B","text":"$48\\pi$"},{"key":"C","text":"$\\frac{64\\pi}{3}$"},{"key":"D","text":"$3\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, find the central angle. The arc length formula is $s = r\\theta$, so $6\\pi = 8\\theta$, giving $\\theta = \\frac{6\\pi}{8} = \\frac{3\\pi}{4}$ radians. The sector area is $A = \\frac{1}{2}r^2\\theta = \\frac{1}{2}(8)^2\\left(\\frac{3\\pi}{4}\\right) = \\frac{1}{2}(64)\\left(\\frac{3\\pi}{4}\\right) = 24\\pi$. The answer $48\\pi$ comes from omitting the $\\frac{1}{2}$ factor in the sector area formula, computing $r^2\\theta$ directly. The answer $\\frac{64\\pi}{3}$ results from using the ratio $\\frac{\\text{arc length}}{\\text{circumference}}$ incorrectly as $\\frac{6\\pi}{16}$ and applying it to the wrong area formula. The answer $3\\pi$ comes from computing only $\\frac{s}{r} \\cdot \\frac{r}{2}$, an incomplete application of the relationships.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM272ABW0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A biologist models the relationship between the concentration of a nutrient ($x$, in milligrams per liter) and the growth rate of a plant ($y$, in centimeters per week) using the equation $y = -0.4x^2 + 4.8x - 6$. According to this model, what concentration of the nutrient produces the maximum growth rate?', NULL, $lyceon_json$[{"key":"A","text":"$4.8$"},{"key":"B","text":"$6$"},{"key":"C","text":"$8.4$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'B', NULL, E'The equation $y = -0.4x^2 + 4.8x - 6$ is a downward-opening parabola, so the maximum occurs at the vertex. The $x$-coordinate of the vertex is $x = \\frac{-b}{2a} = \\frac{-4.8}{2(-0.4)} = \\frac{-4.8}{-0.8} = 6$. Therefore, the concentration that produces the maximum growth rate is $6$ milligrams per liter. The value $4.8$ is the linear coefficient from the equation, not the vertex. The value $8.4$ is the maximum growth rate itself (found by substituting $x = 6$ into the equation), which answers a different question. The value $12$ results from computing $\\frac{-b}{a} = \\frac{-4.8}{-0.4} = 12$, omitting the factor of $2$ in the denominator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM278OWFP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle in the $xy$-plane has the equation $(x - 3)^2 + (y + 2)^2 = 36$. What is the center and the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"Center $(3, -2)$, radius $6$"},{"key":"B","text":"Center $(-3, 2)$, radius $6$"},{"key":"C","text":"Center $(3, -2)$, radius $36$"},{"key":"D","text":"Center $(-3, 2)$, radius $36$"}]$lyceon_json$::jsonb, 'A', NULL, E'The standard form of a circle is $(x - h)^2 + (y - k)^2 = r^2$, where $(h, k)$ is the center and $r$ is the radius. Comparing with $(x - 3)^2 + (y + 2)^2 = 36$, the center is $(3, -2)$ and $r^2 = 36$, so $r = 6$. The answer with center $(-3, 2)$ and radius $6$ results from taking the opposite signs of the constants, forgetting that the standard form uses subtraction. The answer with center $(3, -2)$ and radius $36$ correctly identifies the center but confuses $r^2$ with $r$. The answer with center $(-3, 2)$ and radius $36$ combines both errors.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27C5YMN', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A car rental company charges a flat fee of $\\$25$ plus $\\$0.15$ per mile driven. If $f(m)$ represents the total cost in dollars for driving $m$ miles, which of the following gives $f(m)$ and the cost for driving $200$ miles?', NULL, $lyceon_json$[{"key":"A","text":"$f(m) = 0.15m + 25$; cost is $\\$55$"},{"key":"B","text":"$f(m) = 25m + 0.15$; cost is $\\$5{,}000.15$"},{"key":"C","text":"$f(m) = 0.15m + 25$; cost is $\\$30$"},{"key":"D","text":"$f(m) = 0.15m + 25$; cost is $\\$325$"}]$lyceon_json$::jsonb, 'A', NULL, E'The flat fee is the $y$-intercept and the per-mile charge is the rate of change, giving $f(m) = 0.15m + 25$. For $200$ miles: $f(200) = 0.15(200) + 25 = 30 + 25 = 55$. The formula $25m + 0.15$ reverses the roles of the flat fee and per-mile rate, producing an unreasonable cost. The cost $\\$30$ comes from computing $0.15 \\times 200 = 30$ but omitting the flat fee of $\\$25$. The cost $\\$325$ results from using $\\$1.50$ per mile instead of $\\$0.15$, a decimal placement error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27E3H5E', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'Machine A produces $150$ bolts in $5$ hours, and Machine B produces $200$ bolts in $4$ hours. Both machines start at the same time, but Machine B stops after $4$ hours while Machine A continues working. If the total working period is $6$ hours, how many bolts are produced in total?', NULL, $lyceon_json$[{"key":"A","text":"$350$"},{"key":"B","text":"$380$"},{"key":"C","text":"$420$"},{"key":"D","text":"$480$"}]$lyceon_json$::jsonb, 'B', NULL, E'Machine A''s rate is $\\frac{150}{5} = 30$ bolts per hour, and Machine B''s rate is $\\frac{200}{4} = 50$ bolts per hour. Machine A runs for the full $6$ hours, producing $30 \\times 6 = 180$ bolts. Machine B runs for $4$ hours, producing $50 \\times 4 = 200$ bolts. The total is $180 + 200 = 380$ bolts. The value $350$ comes from calculating only the first $4$ hours of combined output, $80 \\times 4 = 320$, and then adding only one additional hour for Machine A. The value $420$ results from a computational error when summing the contributions. The value $480$ comes from assuming both machines run the full $6$ hours, giving $(30 + 50) \\times 6 = 480$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2825F1Z', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In a right triangle, one acute angle measures $30°$ and the side opposite that angle has length $7$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$7\\sqrt{3}$"},{"key":"B","text":"$\\frac{7}{2}$"},{"key":"C","text":"$14$"},{"key":"D","text":"$\\frac{7\\sqrt{3}}{3}$"}]$lyceon_json$::jsonb, 'C', NULL, E'In a $30°$-$60°$-$90°$ triangle, the side opposite $30°$ is half the hypotenuse. If the side opposite $30°$ is $7$, then the hypotenuse is $2 \\times 7 = 14$. The answer $7\\sqrt{3}$ is the length of the side opposite $60°$, not the hypotenuse. The answer $\\frac{7}{2}$ comes from dividing by $2$ instead of multiplying, reversing the ratio. The answer $\\frac{7\\sqrt{3}}{3}$ results from incorrectly applying the tangent ratio instead of the sine ratio.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28AY2ZC', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'Line $p$ has the equation $4x - 2y = 10$. Line $q$ is perpendicular to line $p$ and passes through the point $(6, 1)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, -2)$"},{"key":"B","text":"$(0, 4)$"},{"key":"C","text":"$(0, 7)$"},{"key":"D","text":"$(0, 13)$"}]$lyceon_json$::jsonb, 'B', NULL, E'Rewriting $4x - 2y = 10$ in slope-intercept form gives $y = 2x - 5$, so line $p$ has slope $2$. A perpendicular line has slope $-\\frac{1}{2}$. Using point-slope form with $(6, 1)$: $y - 1 = -\\frac{1}{2}(x - 6)$, which simplifies to $y = -\\frac{1}{2}x + 4$. The $y$-intercept is $(0, 4)$. The intercept $(0, -2)$ results from using slope $\\frac{1}{2}$ instead of $-\\frac{1}{2}$, a sign error on the negative reciprocal. The intercept $(0, 7)$ comes from using the original slope $2$ instead of the perpendicular slope and solving with the given point. The intercept $(0, 13)$ results from using $-2$ as the perpendicular slope instead of $-\\frac{1}{2}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28WDN6B', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $10$ cm. What is the circumference of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$5\\pi$ cm"},{"key":"B","text":"$10\\pi$ cm"},{"key":"C","text":"$20\\pi$ cm"},{"key":"D","text":"$25\\pi$ cm"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference of a circle is $C = \\pi d$, where $d$ is the diameter. Substituting $d = 10$ gives $C = 10\\pi$ cm. The answer $5\\pi$ results from using the radius ($5$) in the formula $C = \\pi r$ instead of $C = 2\\pi r$, effectively halving the correct answer. The answer $20\\pi$ comes from using $C = 2\\pi d$ instead of $C = \\pi d$, doubling the diameter unnecessarily. The answer $25\\pi$ results from computing the area formula $\\pi r^2 = \\pi(5)^2$ instead of the circumference.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29URWF6', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'What is the larger of the two solutions to the equation $x^2 - 5x + 6 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'Factor the quadratic: $x^2 - 5x + 6 = (x - 2)(x - 3) = 0$. Setting each factor equal to zero gives $x = 2$ or $x = 3$. Since $3 > 2$, the larger solution is $3$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ACQONB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A study finds that students who eat breakfast every day score higher on math tests than students who skip breakfast. The researchers recorded students'' existing eating habits without assigning them to any groups. What type of study was conducted?', NULL, $lyceon_json$[{"key":"A","text":"A controlled experiment"},{"key":"B","text":"An observational study"},{"key":"C","text":"A randomized controlled trial"},{"key":"D","text":"A survey with a margin of error"}]$lyceon_json$::jsonb, 'B', NULL, E'Because the researchers observed students'' existing eating habits without assigning them to eat or skip breakfast, this is an observational study. A controlled experiment or randomized controlled trial would require the researchers to randomly assign students to treatment groups, which did not occur here. Describing this as a survey with a margin of error misidentifies the study design; although surveys can be part of an observational study, the defining feature is the lack of random assignment, not the presence of a margin of error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AXCNZX', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the positive solution of the equation $x^2 = 25$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$-5$"},{"key":"C","text":"$12.5$"},{"key":"D","text":"$625$"}]$lyceon_json$::jsonb, 'A', NULL, E'Taking the square root of both sides gives $x = \\pm 5$. Since the question asks for the positive solution, the answer is $5$. The value $-5$ is a valid solution to the equation but is negative, not what the question asks for. The value $12.5$ results from dividing $25$ by $2$ instead of taking the square root. The value $625$ comes from squaring $25$ rather than taking its square root.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B60LO7', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = 4x - 7$. What is the value of $f(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$-1$"},{"key":"B","text":"$5$"},{"key":"C","text":"$12$"},{"key":"D","text":"$19$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 3$: $f(3) = 4(3) - 7 = 12 - 7 = 5$. The value $-1$ results from computing $4 - 3$ and then subtracting from $7$ in the wrong order, producing a sign error. The value $12$ comes from computing $4(3) = 12$ but neglecting to subtract $7$. The value $19$ comes from computing $4(3) + 7 = 19$, adding instead of subtracting.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
