INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E12TCF', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $\\frac{x^2 - 4}{x^2 + 5x + 6}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{x + 2}{x + 3}$"},{"key":"B","text":"$\\frac{x - 2}{x + 3}$"},{"key":"C","text":"$\\frac{x - 2}{x + 2}$"},{"key":"D","text":"$\\frac{x - 2}{x - 3}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factor the numerator as a difference of squares: $x^2 - 4 = (x - 2)(x + 2)$. Factor the denominator: $x^2 + 5x + 6 = (x + 2)(x + 3)$. Canceling the common factor $(x + 2)$ yields $\\frac{x - 2}{x + 3}$. The expression $\\frac{x + 2}{x + 3}$ results from a sign error when factoring the numerator, keeping $(x + 2)$ instead of $(x - 2)$ after cancellation. The expression $\\frac{x - 2}{x + 2}$ comes from canceling the wrong factor, removing $(x + 3)$ from the denominator instead of $(x + 2)$. The expression $\\frac{x - 2}{x - 3}$ introduces a sign error in the denominator factor.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ERB12G', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of $500$ students from a university with $20{,}000$ students and finds that $68\\%$ of the sample prefers online classes. The margin of error is $3.5$ percentage points at a $95\\%$ confidence level. Which of the following conclusions is best supported by these results?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $68\\%$ of all students at the university prefer online classes."},{"key":"B","text":"Between $64.5\\%$ and $71.5\\%$ of all students at the university likely prefer online classes."},{"key":"C","text":"Between $64.5\\%$ and $71.5\\%$ of the $500$ surveyed students prefer online classes."},{"key":"D","text":"At least $71.5\\%$ of all students at the university prefer online classes."}]$lyceon_json$::jsonb, 'B', NULL, E'The margin of error creates a confidence interval around the sample statistic to estimate the population parameter: $68\\% \\pm 3.5\\%$ gives $64.5\\%$ to $71.5\\%$ for all university students. Claiming exactly $68\\%$ of all students prefer online classes treats the sample statistic as the exact population value, ignoring sampling variability. Applying the interval to the $500$ surveyed students misunderstands the purpose of the margin of error, which estimates the population proportion, not the sample proportion. Stating that at least $71.5\\%$ prefer online classes uses only the upper bound of the interval and overstates the finding.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EY7JEN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'The test scores of five students are $70$, $75$, $80$, $85$, and $90$. What is the mean of these test scores?', NULL, $lyceon_json$[{"key":"A","text":"$75$"},{"key":"B","text":"$80$"},{"key":"C","text":"$85$"},{"key":"D","text":"$90$"}]$lyceon_json$::jsonb, 'B', NULL, E'The mean is computed by adding all values and dividing by the number of values: $\\frac{70 + 75 + 80 + 85 + 90}{5} = \\frac{400}{5} = 80$. The value $75$ results from omitting the highest score or averaging only the first two values. The value $85$ could result from confusing the mean with the second-highest value. The value $90$ is simply the maximum score, not the mean.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
