INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GFOXSY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples are drawn from the same population. Sample 1 consists of $400$ people, of whom $62\\%$ support a policy, with a margin of error of $4.8$ percentage points. Sample 2 consists of $1{,}600$ people, of whom $58\\%$ support the same policy, with a margin of error of $2.4$ percentage points. Which of the following statements is best supported by these results?', NULL, $lyceon_json$[{"key":"A","text":"Sample 1 provides a more accurate estimate because its approval percentage is higher."},{"key":"B","text":"The two samples contradict each other, so neither result can be considered reliable."},{"key":"C","text":"The results cannot be compared because the sample sizes are different."},{"key":"D","text":"Sample 2 provides a more precise estimate because its margin of error is smaller."}]$lyceon_json$::jsonb, 'D', NULL, E'Precision of an estimate is reflected in the size of the margin of error: a smaller margin of error means the confidence interval is narrower, indicating a more precise estimate. With a margin of error of $2.4$ percentage points, the second sample produces a narrower interval ($55.6\\%$ to $60.4\\%$) compared to the first sample''s interval ($57.2\\%$ to $66.8\\%$). A higher sample percentage does not make an estimate more accurate; accuracy relates to how close the estimate is to the true value, which is unknown. The two intervals overlap ($57.2\\%$ to $60.4\\%$), so the results are consistent rather than contradictory. Samples of different sizes can still be meaningfully compared; larger samples generally produce more precise estimates because the margin of error decreases as sample size increases.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GKVPKP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'The price of an item is increased from $\\$80$ to $\\$100$. What is the percent increase in the price?', NULL, $lyceon_json$[{"key":"A","text":"$20\\%$"},{"key":"B","text":"$25\\%$"},{"key":"C","text":"$80\\%$"},{"key":"D","text":"$125\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The amount of increase is $\\$100 - \\$80 = \\$20$. The percent increase is $\\frac{20}{80} \\times 100 = 25\\%$. The value $20\\%$ results from dividing the change by the new price ($\\frac{20}{100}$) instead of the original price. The value $80\\%$ comes from computing the ratio $\\frac{80}{100}$ and confusing it with the percent change. The value $125\\%$ results from computing $\\frac{100}{80} = 1.25$ and reporting it as a percentage without recognizing that the percent increase is $1.25 - 1 = 0.25$, or $25\\%$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GN1EX6', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows the relationship between the number of hours studied and test scores for $10$ students. The line of best fit has equation $y = 5x + 60$, where $x$ is hours studied and $y$ is the predicted test score. According to this model, what is the predicted test score for a student who studies $6$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$66$"},{"key":"B","text":"$85$"},{"key":"C","text":"$90$"},{"key":"D","text":"$95$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 6$ into the equation $y = 5x + 60$ gives $y = 5(6) + 60 = 30 + 60 = 90$. The value $66$ comes from adding $6$ to $60$ instead of multiplying $5 \\times 6$ first. The value $85$ results from an arithmetic error such as computing $5 \\times 5 + 60$. The value $95$ results from an arithmetic slip such as computing $5 \\times 7 + 60$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GQF5NS', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $200$ voters in a town found that $54\\%$ support building a new park. The margin of error for this estimate is $4$ percentage points. Which of the following is a plausible range for the percentage of all voters in the town who support building the new park?', NULL, $lyceon_json$[{"key":"A","text":"$50\\%$ to $58\\%$"},{"key":"B","text":"$54\\%$ to $58\\%$"},{"key":"C","text":"$52\\%$ to $56\\%$"},{"key":"D","text":"$46\\%$ to $62\\%$"}]$lyceon_json$::jsonb, 'A', NULL, E'The plausible range is found by subtracting and adding the margin of error to the sample estimate: $54\\% - 4\\% = 50\\%$ and $54\\% + 4\\% = 58\\%$, giving a range of $50\\%$ to $58\\%$. The range $54\\%$ to $58\\%$ results from adding the margin of error but not subtracting it, completing only half the calculation. The range $52\\%$ to $56\\%$ comes from using half the margin of error in each direction. The range $46\\%$ to $62\\%$ results from doubling the margin of error to $8$ percentage points.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H6QPP5', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A store charges $\\$8$ per item plus a flat shipping fee of $\\$15$. A customer wants to spend no more than $\\$75$. What is the greatest number of items the customer can order?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$7$"},{"key":"C","text":"$8$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'B', NULL, E'Set up the inequality $8n + 15 \\leq 75$. Subtract $15$ from both sides to get $8n \\leq 60$, then divide by $8$ to get $n \\leq 7.5$. Since the number of items must be a whole number, the greatest value is $7$. The answer $8$ incorrectly rounds $7.5$ up, but the customer would then spend $8(8) + 15 = 79$, which exceeds the budget. The answer $9$ results from ignoring the shipping fee entirely and computing $75 \\div 8 \\approx 9.4$, then rounding down. The answer $6$ comes from a computational error in the division step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I6NQMW', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'If $\\frac{2(x - 4)}{3} = 10$, what is the value of $x - 1$?', NULL, $lyceon_json$[{"key":"A","text":"$14$"},{"key":"B","text":"$15$"},{"key":"C","text":"$18$"},{"key":"D","text":"$19$"}]$lyceon_json$::jsonb, 'C', NULL, E'Multiplying both sides by $3$ gives $2(x - 4) = 30$. Dividing by $2$ gives $x - 4 = 15$, so $x = 19$ and $x - 1 = 18$. The value $14$ results from solving $x - 4 = 15$ correctly but then computing $19 - 5$ instead of $19 - 1$. The value $15$ comes from finding $x - 4 = 15$ and reporting that intermediate result instead of computing $x - 1$. The value $19$ is $x$ itself, not $x - 1$ as the question asks.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IG8NUT', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'If $-3(2x - 4) + 5 \\leq 2x + 1$, what is the least integer value of $x$ that satisfies the inequality?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2', ARRAY['2'], E'Distribute $-3$ across $(2x - 4)$ to get $-6x + 12 + 5 \\leq 2x + 1$, which simplifies to $-6x + 17 \\leq 2x + 1$. Add $6x$ to both sides: $17 \\leq 8x + 1$. Subtract $1$ from both sides: $16 \\leq 8x$. Divide by $8$: $2 \\leq x$, or equivalently $x \\geq 2$. Since the inequality includes $2$, the least integer satisfying it is $2$. A common error is distributing $-3$ incorrectly as $-6x - 12$ instead of $-6x + 12$, which would yield $x \\geq -1$. Another error is combining $12 + 5$ as $7$ instead of $17$, leading to a different result.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IIR3FB', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'From the top of a vertical cliff $80$ meters high, the angle of depression to a boat on the water is $35°$. What is the horizontal distance from the base of the cliff to the boat, to the nearest whole meter? (Use $\\tan(35°) \\approx 0.7002$.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '114', ARRAY['114'], E'The angle of depression from the top of the cliff equals the angle of elevation from the boat to the top of the cliff, which is $35°$. In the right triangle formed, the cliff height ($80$ m) is the side opposite the $35°$ angle, and the horizontal distance $d$ is the side adjacent. Using $\\tan(35°) = \\frac{80}{d}$, solving gives $d = \\frac{80}{\\tan(35°)} = \\frac{80}{0.7002} \\approx 114.25$, which rounds to $114$ meters.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J37QR4', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A cone has a volume of $48\\pi$ cubic inches and a height of $9$ inches. What is the radius of the cone, in inches?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'The volume of a cone is $V = \\frac{1}{3}\\pi r^2 h$. Setting $48\\pi = \\frac{1}{3}\\pi r^2(9)$ and simplifying gives $48\\pi = 3\\pi r^2$. Dividing both sides by $3\\pi$ yields $r^2 = 16$, so $r = 4$ inches.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JRIR2Y', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, angle $P$ measures $40°$ and angle $Q$ measures $75°$. What is the measure, in degrees, of the exterior angle at vertex $R$?', NULL, $lyceon_json$[{"key":"A","text":"$65°$"},{"key":"B","text":"$105°$"},{"key":"C","text":"$115°$"},{"key":"D","text":"$140°$"}]$lyceon_json$::jsonb, 'C', NULL, E'The interior angle at $R$ is $180° - 40° - 75° = 65°$. The exterior angle at $R$ is supplementary to this interior angle: $180° - 65° = 115°$. Equivalently, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles: $40° + 75° = 115°$. The answer $65°$ is the interior angle at $R$, not the exterior angle. The answer $105°$ results from finding the supplement of $75°$ rather than the exterior angle at $R$. The answer $140°$ comes from computing $180° - 40°$, using only one interior angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L568EO', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'For which value of $c$ does the system of equations $y = x^2 + 2x$ and $y = 3x + c$ have exactly one real solution?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1}{4}$"},{"key":"B","text":"$-\\frac{1}{4}$"},{"key":"C","text":"$-1$"},{"key":"D","text":"$0$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting the equations equal gives $x^2 + 2x = 3x + c$, which simplifies to $x^2 - x - c = 0$. For exactly one real solution, the discriminant must equal zero: $(-1)^2 - 4(1)(-c) = 0$, so $1 + 4c = 0$, yielding $c = -\\frac{1}{4}$. The value $\\frac{1}{4}$ results from a sign error when solving $1 + 4c = 0$. The value $-1$ comes from incorrectly setting the discriminant expression to $1 - 4c = 0$ by mishandling the sign of $c$ during rearrangement. The value $0$ comes from assuming the system has one solution only when the constant term of the rearranged quadratic is zero.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LF97BG', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $x^2 - 9x + 20$?', NULL, $lyceon_json$[{"key":"A","text":"$(x - 4)(x + 5)$"},{"key":"B","text":"$(x + 4)(x + 5)$"},{"key":"C","text":"$(x - 4)(x - 5)$"},{"key":"D","text":"$(x - 2)(x - 10)$"}]$lyceon_json$::jsonb, 'C', NULL, E'To factor $x^2 - 9x + 20$, find two numbers that multiply to $20$ and add to $-9$. Those numbers are $-4$ and $-5$, giving $(x - 4)(x - 5)$. Expanding confirms: $x^2 - 5x - 4x + 20 = x^2 - 9x + 20$. The expression $(x - 4)(x + 5)$ expands to $x^2 + x - 20$, which has the wrong middle term and constant sign. The expression $(x + 4)(x + 5)$ expands to $x^2 + 9x + 20$, reversing the sign of the middle term. The expression $(x - 2)(x - 10)$ expands to $x^2 - 12x + 20$, using a factor pair of $20$ that does not sum to $-9$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LZPKOI', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'If $4(3x - 2) - 5(x - 3) = 3(x + 1)$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-1', ARRAY['-1'], E'Expanding the left side: $12x - 8 - 5x + 15 = 3x + 3$. Combining like terms on the left gives $7x + 7 = 3x + 3$. Subtracting $3x$ from both sides: $4x + 7 = 3$. Subtracting $7$ from both sides: $4x = -4$. Dividing by $4$: $x = -1$.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M8YEGL', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What is the value of $x$ in the equation $3x + 9 = 24$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$7$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'B', NULL, E'Subtracting $9$ from both sides gives $3x = 15$, and dividing both sides by $3$ gives $x = 5$. The value $3$ results from dividing $24$ by $3$ first and then subtracting a misapplied constant. The value $7$ comes from subtracting $9$ from $24$ to get $15$ and then adding $2$ instead of dividing by $3$. The value $11$ comes from dividing $24$ by $3$ to get $8$ and then adding $3$, reversing the subtraction step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OKIBJF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A car travels $180$ miles using $6$ gallons of gasoline. At this rate, how many gallons of gasoline would the car need to travel $450$ miles?', NULL, $lyceon_json$[{"key":"A","text":"$12$"},{"key":"B","text":"$15$"},{"key":"C","text":"$18$"},{"key":"D","text":"$75$"}]$lyceon_json$::jsonb, 'B', NULL, E'The car''s fuel efficiency is $\\frac{180}{6} = 30$ miles per gallon. To find the gallons needed for $450$ miles, divide: $\\frac{450}{30} = 15$ gallons. The value $12$ results from computing an intermediate step but not completing the full calculation. The value $18$ comes from an arithmetic mistake when dividing $450$ by $30$. The value $75$ results from dividing $450$ by $6$ directly, setting up the proportion incorrectly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P2RZ8Y', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two angles are supplementary. If one angle measures $115°$, what is the measure of the other angle?', NULL, $lyceon_json$[{"key":"A","text":"$25°$"},{"key":"B","text":"$55°$"},{"key":"C","text":"$65°$"},{"key":"D","text":"$245°$"}]$lyceon_json$::jsonb, 'C', NULL, E'Supplementary angles sum to $180°$. The other angle is $180° - 115° = 65°$. The answer $25°$ results from confusing supplementary with complementary angles and subtracting from $90°$ instead of $180°$. The answer $55°$ comes from an arithmetic error when subtracting $115$ from $180$. The answer $245°$ results from adding the two values instead of subtracting.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q42DHI', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'grid_in', E'The function $h(x) = -2(x + 1)^2 + 18$ intersects the $x$-axis at two points. What is the positive $x$-value where $h(x) = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2', ARRAY['2'], E'Setting $h(x) = 0$ gives $-2(x + 1)^2 + 18 = 0$. Adding $2(x + 1)^2$ to both sides yields $18 = 2(x + 1)^2$, so $(x + 1)^2 = 9$. Taking the square root gives $x + 1 = \\pm 3$, which means $x = 2$ or $x = -4$. The positive value is $2$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QXB8WT', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $3(x + 4) - 2x$?', NULL, $lyceon_json$[{"key":"A","text":"$x + 12$"},{"key":"B","text":"$x + 4$"},{"key":"C","text":"$5x + 4$"},{"key":"D","text":"$x - 12$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing gives $3x + 12 - 2x$, which simplifies to $x + 12$. The expression $x + 4$ results from failing to distribute the $3$ across the $4$ in the parentheses. The expression $5x + 4$ comes from incorrectly adding $3x$ and $2x$ instead of subtracting, and not distributing the $3$ to the constant term. The expression $x - 12$ results from a sign error when combining $+12$ from the distribution.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TDP2E4', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'grid_in', E'The equation $ax + by = 12$ represents a line that passes through $(4, 0)$ and $(0, 3)$. What is the value of $a + b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Substituting $(4, 0)$ into $ax + by = 12$ gives $4a = 12$, so $a = 3$. Substituting $(0, 3)$ into $ax + by = 12$ gives $3b = 12$, so $b = 4$. Therefore $a + b = 3 + 4 = 7$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TR3HUW', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'If $f(x) = x^2 - 4$, what is the value of $f(5)$?', NULL, $lyceon_json$[{"key":"A","text":"$21$"},{"key":"B","text":"$1$"},{"key":"C","text":"$29$"},{"key":"D","text":"$-21$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $5$ into the function gives $f(5) = 5^2 - 4 = 25 - 4 = 21$. The value $1$ results from computing $5 - 4$ without squaring, confusing $x^2$ with $x$. The value $29$ comes from adding $25 + 4$ instead of subtracting. The value $-21$ results from a sign error, negating the entire result.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TZSZVV', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'A line passes through the points $(0, 3)$ and $(2, 7)$. Which of the following is the equation of the line?', NULL, $lyceon_json$[{"key":"A","text":"$y = 2x + 3$"},{"key":"B","text":"$y = 2x + 7$"},{"key":"C","text":"$y = 3x + 2$"},{"key":"D","text":"$y = 4x + 3$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $\\frac{7 - 3}{2 - 0} = \\frac{4}{2} = 2$, and the $y$-intercept is $3$ since the line passes through $(0, 3)$. The equation is $y = 2x + 3$. The equation $y = 2x + 7$ uses the correct slope but substitutes the other $y$-coordinate as the intercept. The equation $y = 3x + 2$ swaps the slope and intercept values. The equation $y = 4x + 3$ uses the numerator of $4$ as the slope without dividing by the run of $2$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UH36AL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In the figure, lines $m$ and $n$ are parallel, and line $t$ is a transversal. One of the angles formed where $t$ crosses $m$ measures $(3x + 10)°$. The alternate interior angle formed where $t$ crosses $n$ measures $(5x - 30)°$. What is the measure, in degrees, of the angle $(3x + 10)°$?', NULL, $lyceon_json$[{"key":"A","text":"$20$"},{"key":"B","text":"$50$"},{"key":"C","text":"$70$"},{"key":"D","text":"$110$"}]$lyceon_json$::jsonb, 'C', NULL, E'Alternate interior angles formed by parallel lines and a transversal are equal, so $3x + 10 = 5x - 30$. Solving: $10 + 30 = 5x - 3x$, which gives $40 = 2x$, so $x = 20$. Substituting back: $3(20) + 10 = 70°$. The answer $20$ is the value of $x$, not the angle measure. The answer $50$ comes from setting the angles as supplementary ($3x + 10 + 5x - 30 = 180$) instead of equal. The answer $110$ results from computing the supplement of $70°$, which would be the co-interior angle, not the alternate interior angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
