INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VKYCSH', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'What are all values of $x$ that satisfy $5x + 2 > 17$?', NULL, $lyceon_json$[{"key":"A","text":"$x < 3$"},{"key":"B","text":"$x > 3$"},{"key":"C","text":"$x > 15$"},{"key":"D","text":"$x > \\frac{19}{5}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Subtract $2$ from both sides of $5x + 2 > 17$ to get $5x > 15$, then divide both sides by $5$ to get $x > 3$. The result $x > 15$ comes from subtracting $2$ but not dividing by $5$, stopping at an intermediate step. The result $x > \\frac{19}{5}$ comes from incorrectly adding $2$ to $17$ instead of subtracting. The result $x < 3$ reverses the direction of the inequality without justification.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VY3WXL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the number of hours of sunlight per day ($x$) and the average daily temperature in degrees Fahrenheit ($y$) over $12$ months. The line of best fit is $y = 3.2x + 28$. In this context, what does the slope $3.2$ represent?', NULL, $lyceon_json$[{"key":"A","text":"The predicted temperature when there are $0$ hours of sunlight"},{"key":"B","text":"The predicted increase in temperature, in degrees Fahrenheit, for each additional hour of sunlight per day"},{"key":"C","text":"The total number of degrees the temperature increases over $12$ months"},{"key":"D","text":"The average number of hours of sunlight per day"}]$lyceon_json$::jsonb, 'B', NULL, E'In the equation $y = 3.2x + 28$, the slope $3.2$ represents the predicted change in temperature (in degrees Fahrenheit) for each one-unit increase in hours of sunlight per day. The interpretation that $3.2$ is the predicted temperature at $0$ hours of sunlight confuses the slope with the $y$-intercept of $28$. The claim that $3.2$ represents the total temperature increase over $12$ months misinterprets the slope as a cumulative total rather than a per-unit rate. The claim that $3.2$ is the average hours of sunlight per day confuses the independent and dependent variables.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X56IPA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'Researchers randomly assigned $100$ agricultural plots to receive a new fertilizer and $100$ plots to receive a standard fertilizer. After one growing season, the plots receiving the new fertilizer produced an average of $15\\%$ more crop yield than the plots receiving the standard fertilizer. Which of the following conclusions is most justified?', NULL, $lyceon_json$[{"key":"A","text":"The new fertilizer is associated with higher crop yield, but a causal relationship cannot be established."},{"key":"B","text":"The new fertilizer caused the increase in crop yield."},{"key":"C","text":"The study proves the new fertilizer will always produce $15\\%$ more yield under any conditions."},{"key":"D","text":"The results are invalid because factors other than fertilizer could have affected crop yield."}]$lyceon_json$::jsonb, 'B', NULL, E'Because the study used random assignment to divide plots into treatment and control groups, it is a randomized controlled experiment. Random assignment controls for confounding variables by distributing them approximately equally between groups, which allows causal conclusions. Claiming only an association ignores that random assignment specifically enables causal inference. Stating the fertilizer will always produce $15\\%$ more yield overgeneralizes beyond the conditions of the study. Dismissing the results because other factors could have affected yield misunderstands the purpose of random assignment, which is designed to balance such confounding factors across groups.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XKCXKD', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylinder has a radius of $3$ cm and a height of $10$ cm. What is the volume of the cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$30\\pi$ cm$^3$"},{"key":"B","text":"$90\\pi$ cm$^3$"},{"key":"C","text":"$60\\pi$ cm$^3$"},{"key":"D","text":"$900\\pi$ cm$^3$"}]$lyceon_json$::jsonb, 'B', NULL, E'The volume of a cylinder is $V = \\pi r^2 h$. Substituting $r = 3$ and $h = 10$ gives $V = \\pi(3)^2(10) = 90\\pi$ cm$^3$. The answer $30\\pi$ comes from using $r$ instead of $r^2$ in the formula, computing $\\pi(3)(10)$. The answer $60\\pi$ results from using $2r$ instead of $r^2$, computing $\\pi(2)(3)(10)$. The answer $900\\pi$ comes from squaring both $r$ and $h$, computing $\\pi(3)^2(10)^2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YQ9S95', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set contains $10$ values with a mean of $15$. When an $11$th value is added, the mean increases to $16$. What is the $11$th value?', NULL, $lyceon_json$[{"key":"A","text":"$16$"},{"key":"B","text":"$21$"},{"key":"C","text":"$26$"},{"key":"D","text":"$31$"}]$lyceon_json$::jsonb, 'C', NULL, E'The original $10$ values have a sum of $10 \\times 15 = 150$. After adding the $11$th value, the new sum must be $11 \\times 16 = 176$. Therefore, the $11$th value is $176 - 150 = 26$. The value $16$ comes from assuming the new value equals the new mean, which is a conceptual error. The value $21$ results from computing $16 \\times 11 = 176$ but then subtracting only $155$ instead of $150$. The value $31$ results from an arithmetic slip such as computing $11 \\times 16 = 181$ instead of $176$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20A3BS3', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'For decades, astronomers assumed that most planetary systems would resemble our own, with small rocky planets orbiting close to their star and gas giants farther out. The discovery of ''hot Jupiters'' — massive gas planets in tight orbits around their host stars — upended this expectation. These findings forced researchers to revise their models of planetary formation, acknowledging that gravitational interactions can cause large planets to migrate inward after forming in the outer reaches of a system.', $lyceon_json$[{"key":"A","text":"It presents an established assumption, introduces a finding that contradicted it, and explains how scientists adjusted their understanding."},{"key":"B","text":"It proposes a new theory of planetary formation and provides evidence supporting that theory."},{"key":"C","text":"It contrasts two competing hypotheses about planetary orbits and evaluates which has more support."},{"key":"D","text":"It chronicles the history of telescope technology and its impact on astronomical discoveries."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice describing the structure as an established assumption, a contradicting finding, and an adjustment. The passage opens with what astronomers assumed, then introduces hot Jupiters as a discovery that "upended this expectation," and concludes with how researchers revised their models. The choice about proposing a new theory mischaracterizes the structure; the passage describes how an existing view was updated in response to evidence, not the advocacy of an original theory. The choice about two competing hypotheses is inaccurate because the passage presents one original assumption and its revision, not a debate between rival positions. The choice about telescope history introduces a subject the passage never discusses.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21DLCM9', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The company''s new sustainability initiative requires employees to reduce paper usage, to minimize energy consumption during off-peak hours, and ______ reusable containers for all meals consumed on the premises.', $lyceon_json$[{"key":"A","text":"that they use"},{"key":"B","text":"using"},{"key":"C","text":"to use"},{"key":"D","text":"they should use"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence establishes a three-part parallel list governed by "requires employees": "to reduce," "to minimize," and a third infinitive. Parallel structure demands that all three elements share the same grammatical form, so "to use" is the only choice that maintains the infinitive pattern. The subordinate clause "that they use" breaks the infinitive pattern by introducing a finite clause. The gerund "using" shifts to a participial form that does not match the established infinitive construction. The independent clause "they should use" similarly abandons the infinitive structure and introduces a new subject and modal verb.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22KZ175', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time the rescue team arrived at the remote mountain village, the floodwaters ______ most of the access roads, and the only remaining route into the valley was a narrow footpath along the ridge.', $lyceon_json$[{"key":"A","text":"destroy"},{"key":"B","text":"had destroyed"},{"key":"C","text":"have destroyed"},{"key":"D","text":"would destroy"}]$lyceon_json$::jsonb, 'B', NULL, E'The phrase "by the time the rescue team arrived" signals that the destruction of the roads was completed before another past event. This sequence requires the past perfect tense, "had destroyed," to indicate that one past action preceded another. The present tense "destroy" is incompatible with the past-tense narrative. The present perfect "have destroyed" connects a past action to the present, which conflicts with the entirely past-tense context of the sentence. The conditional "would destroy" implies a hypothetical or future-in-the-past action, but the coordinating clause "the only remaining route was a narrow footpath" confirms that the destruction had already occurred.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22VKNEY', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does "economy" most nearly mean?', E'The author''s prose is notable for its economy; each sentence conveys maximum meaning with the fewest possible words, leaving no room for ornamental flourishes or superfluous detail.', $lyceon_json$[{"key":"A","text":"efficiency"},{"key":"B","text":"prosperity"},{"key":"C","text":"marketplace"},{"key":"D","text":"regulation"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "efficiency." Here, "economy" describes the author''s concise writing style — achieving maximum effect with minimal words. The passage reinforces this meaning with phrases like "fewest possible words" and "no room for ornamental flourishes." "Prosperity" refers to financial wealth or success, which cannot logically characterize a quality of prose. "Marketplace" denotes a venue for commercial exchange and produces an incoherent sentence when substituted: prose cannot be notable for its marketplace. "Regulation" implies imposed rules or governmental controls, which does not capture the deliberate conciseness the passage describes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24IV51O', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Dr. Elena Vasquez, who has spent over two decades researching the cognitive effects of sleep deprivation on emergency room ______ recently published a study suggesting that physicians working shifts longer than sixteen hours show measurable declines in diagnostic accuracy.', $lyceon_json$[{"key":"A","text":"physicians, recently"},{"key":"B","text":"physicians recently"},{"key":"C","text":"physicians; recently"},{"key":"D","text":"physicians. Recently"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence''s main clause is "Dr. Elena Vasquez recently published a study," interrupted by the nonrestrictive relative clause "who has spent over two decades researching the cognitive effects of sleep deprivation on emergency room physicians." A nonrestrictive clause must be enclosed by a pair of commas; the opening comma appears after "Vasquez," so a closing comma is required after "physicians" to mark the end of the relative clause and resume the main clause. Omitting the closing comma fails to properly demarcate the nonrestrictive clause. A semicolon cannot appear in the middle of a single main clause. A period after "physicians" severs the main clause, leaving "Dr. Elena Vasquez, who has spent over two decades researching...physicians" as a sentence fragment with no main verb.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW265W0IC', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'A collection of rare manuscripts dating from the fifteenth century ______ housed in the university''s climate-controlled archive, where scholars can examine the texts by appointment.', $lyceon_json$[{"key":"A","text":"are"},{"key":"B","text":"is"},{"key":"C","text":"were"},{"key":"D","text":"have been"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is "collection," a singular noun. Although "manuscripts" appears nearby, it is the object of the preposition "of" and does not determine the verb''s number. The singular subject requires the singular verb "is." The plural forms "are" and "have been" incorrectly treat "manuscripts" as the subject. The past tense "were" is inconsistent with the present-tense context established by "can examine" later in the sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26VCBKJ', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does "address" most nearly mean?', E'During the town meeting, the mayor attempted to address the residents'' concerns about the new construction project by presenting updated safety reports and revised timelines.', $lyceon_json$[{"key":"A","text":"respond to"},{"key":"B","text":"locate"},{"key":"C","text":"label"},{"key":"D","text":"memorize"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "respond to." In the passage, the mayor is attempting to deal with the residents'' concerns by presenting safety reports. "Locate" refers to finding a physical position, which produces an incoherent sentence when substituted: one cannot "locate" concerns in this context. "Label" means to categorize or tag something, which does not describe the mayor''s effort to engage with and alleviate the concerns. "Memorize" means to commit information to memory, which is entirely unrelated to the act of handling or resolving an issue.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27N8QZ1', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Researchers hypothesized that increased sunlight exposure would improve student performance on standardized ______ the study found no significant difference between students in sunlit classrooms and those in windowless rooms.', $lyceon_json$[{"key":"A","text":"tests, the"},{"key":"B","text":"tests; however, the"},{"key":"C","text":"tests however, the"},{"key":"D","text":"tests, however the"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice uses a semicolon before the conjunctive adverb "however" and a comma after it to properly join two contrasting independent clauses. The hypothesis predicted improvement, but the study found no difference, so a contrast signal is appropriate. Using only a comma before the second independent clause creates a comma splice. Omitting the semicolon before "however" produces a fused sentence at the clause boundary. Placing a comma before "however" without a semicolon creates a comma splice, and omitting the comma after "however" violates the convention of setting off conjunctive adverbs with commas.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28KZ3JU', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The director of the wildlife rehabilitation center explained that the decision to release the injured hawk back into the wild would ultimately depend on whether the lead veterinarian and ______ could confirm that the bird had regained full flight capability.', $lyceon_json$[{"key":"A","text":"she"},{"key":"B","text":"her"},{"key":"C","text":"herself"},{"key":"D","text":"hers"}]$lyceon_json$::jsonb, 'A', NULL, E'The pronoun is part of the compound subject "the lead veterinarian and [pronoun]," which serves as the subject of the verb "could confirm." A subject position requires the nominative case, so "she" is correct. The objective case "her" is used for objects of verbs or prepositions, not subjects. The reflexive "herself" requires a same-clause antecedent to reflect back to, which is absent here. The possessive "hers" functions as a pronoun replacing a noun phrase and cannot serve as a subject of "could confirm" in this construction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29CFCTJ', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'In the early twentieth century, many linguists believed that bilingualism confused children and hindered their cognitive development. _______ research conducted since the 1960s has consistently shown that bilingual individuals often outperform monolinguals on tasks requiring attention control and mental flexibility.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"However,"},{"key":"C","text":"Specifically,"},{"key":"D","text":"Accordingly,"}]$lyceon_json$::jsonb, 'B', NULL, E'"However" correctly signals that the second sentence contradicts the belief described in the first: early linguists thought bilingualism was harmful, but subsequent research has shown cognitive benefits. "Similarly" incorrectly implies the second sentence echoes the first, when in fact it presents an opposing finding. "Specifically" incorrectly implies the second sentence provides a detailed elaboration of the first, but the second sentence refutes rather than expands upon the earlier claim. "Accordingly" incorrectly implies the research findings logically follow from the early belief, when the findings actually contradict that belief.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29LO5FM', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would Vasquez (Text 2) most likely respond to Whitfield''s argument in Text 1?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2B19WH7', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Archaeologist Fatima al-Rashid has examined ceramic trade goods found at inland sites along the ancient Silk Road. Conventionally, the presence of Chinese-made ceramics at Central Asian sites has been interpreted as evidence of direct, long-distance trade between Chinese producers and Central Asian consumers. However, al-Rashid''s chemical analysis of ceramic glazes from sites in present-day Uzbekistan revealed that many pieces previously classified as Chinese imports were in fact produced locally using techniques borrowed from Chinese traditions. The local ceramics closely replicated Chinese decorative styles but used clays and mineral pigments native to Central Asia. Al-Rashid''s findings suggest that the spread of Chinese ceramic styles along the Silk Road was driven less by the physical transport of goods than by ________', $lyceon_json$[{"key":"A","text":"the transmission of specialized production knowledge across regions."},{"key":"B","text":"Central Asian merchants' preference for locally made goods over Chinese imports."},{"key":"C","text":"the declining quality of ceramics produced in China during this period."},{"key":"D","text":"political alliances that required Central Asian artisans to adopt Chinese artistic conventions."}]$lyceon_json$::jsonb, 'A', NULL, E'Al-Rashid found that ceramics previously thought to be Chinese imports were locally produced using borrowed Chinese techniques, which means the spread of Chinese styles occurred through the transfer of production knowledge rather than through the shipment of physical goods. The choice about merchants preferring local goods goes beyond the evidence; the passage shows local production occurred but says nothing about merchant preferences or conscious choices between local and imported wares. The choice about declining Chinese ceramic quality introduces an explanation not supported by any detail in the passage. The choice about political alliances requiring adoption of Chinese conventions is unsupported; the passage provides no evidence of political mandates or alliances influencing artisans'' practices.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BODAL6', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the main idea of the text?', E'The concept of "rewilding" — reintroducing native species to ecosystems from which they have disappeared — has gained traction among conservationists, but ecologist Priya Chaudhuri argues that its appeal often overshadows its complexity. In a 2024 review, Chaudhuri examined twelve rewilding projects across Europe and found that success depended less on the species reintroduced than on the surrounding land-use context. Projects embedded in landscapes still dominated by agriculture or urban development frequently failed because the reintroduced species lacked sufficient habitat connectivity. Chaudhuri concluded that rewilding advocates must prioritize landscape-level planning over charismatic species introductions if they hope to achieve durable ecological outcomes.', $lyceon_json$[{"key":"A","text":"Rewilding projects are more likely to succeed when they prioritize landscape connectivity over the selection of particular species for reintroduction."},{"key":"B","text":"Rewilding has proven ineffective as a conservation strategy because most reintroduced species cannot adapt to modern European landscapes."},{"key":"C","text":"Chaudhuri's review found that rewilding projects succeed primarily in regions where agriculture has been abandoned."},{"key":"D","text":"The popularity of rewilding among conservationists is justified by the high success rate of species reintroduction programs in Europe."}]$lyceon_json$::jsonb, 'A', NULL, E'Chaudhuri''s central argument is that landscape-level planning — particularly habitat connectivity — matters more than which species are reintroduced, making the choice about prioritizing landscape connectivity the best summary of the main idea. The choice declaring rewilding ineffective overstates Chaudhuri''s position; she critiques the approach''s complexity but does not dismiss it entirely, and the passage notes that some projects succeeded. The choice about projects succeeding where agriculture has been abandoned misreads the passage, which states that projects surrounded by agriculture failed, but does not claim success required agricultural abandonment. The choice about rewilding''s popularity being justified contradicts the passage, which states that rewilding''s appeal "often overshadows its complexity."', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FCR643', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'A researcher hypothesizes that social isolation in adolescence leads to measurable changes in brain structure. Which finding from the text, if valid, would most directly support this hypothesis?', E'Neuroscientist Tomás Herrera and his team studied brain development in adolescents aged 13 to 17 over a three-year period. Participants who reported consistently low levels of social interaction showed reduced volume in the prefrontal cortex compared with peers who reported moderate to high social engagement. Herrera noted, however, that the study could not determine whether the structural differences preceded or resulted from the social isolation, since participants were not randomly assigned to conditions. Additionally, participants with lower social interaction were more likely to report symptoms of anxiety, which itself has been linked to prefrontal cortex changes in prior studies.', $lyceon_json$[{"key":"A","text":"Participants with low social interaction showed reduced prefrontal cortex volume compared with more socially engaged peers."},{"key":"B","text":"The study could not determine whether structural brain differences preceded or resulted from social isolation."},{"key":"C","text":"Participants with lower social interaction were more likely to report symptoms of anxiety."},{"key":"D","text":"The study followed adolescents aged 13 to 17 over a three-year period."}]$lyceon_json$::jsonb, 'A', NULL, E'The finding that socially isolated participants had reduced prefrontal cortex volume directly supports the hypothesis that social isolation leads to measurable brain changes, since it identifies a structural difference associated with isolation. The finding about the study''s inability to establish causal direction actually undermines rather than supports the hypothesis, since it highlights the study''s limitation. The finding about anxiety symptoms is relevant to social isolation but does not directly support the claim about brain structure changes caused by isolation, since anxiety itself may be responsible for the prefrontal cortex differences. The finding about the study''s duration and age range describes methodology rather than providing evidence for the hypothesis.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FEEDBX', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the text as a whole?', E'Honeybees communicate the location of food sources through a series of movements known as the waggle dance. A forager bee that has found nectar returns to the hive and performs a figure-eight pattern, vibrating its abdomen. The angle of the dance relative to the sun indicates the direction of the food, while the duration of the waggle phase signals the distance.', $lyceon_json$[{"key":"A","text":"It explains how honeybees convey information about food sources to other bees."},{"key":"B","text":"It argues that honeybees are more intelligent than other insects."},{"key":"C","text":"It compares the waggle dance to other forms of animal communication."},{"key":"D","text":"It describes the nutritional needs of a typical honeybee colony."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that the text explains how honeybees convey information about food sources. The passage describes the waggle dance mechanism — the figure-eight pattern, the angle relative to the sun indicating direction, and the waggle duration signaling distance — all serving to communicate location. The choice about honeybee intelligence introduces a comparative claim the passage never makes. The choice about comparing the waggle dance to other communication forms is unsupported; the passage discusses only the waggle dance without referencing other species. The choice about nutritional needs misidentifies the topic entirely, as the passage addresses communication behavior, not diet.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FH2RDR', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'The Arctic tern holds the record for the longest annual migration of any animal, traveling roughly 44,000 miles round trip between the Arctic and Antarctic. _______ the bird experiences two summers each year, giving it more daylight exposure than any other creature on Earth.', $lyceon_json$[{"key":"A","text":"As a result,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"For instance,"},{"key":"D","text":"Nevertheless,"}]$lyceon_json$::jsonb, 'A', NULL, E'"As a result" is correct because the second sentence describes a consequence of the Arctic tern''s pole-to-pole migration: by traveling between the Arctic and Antarctic, the bird experiences two summers and maximum daylight. "In contrast" incorrectly signals opposition, but the two sentences do not present conflicting ideas. "For instance" incorrectly signals that the second sentence is an example of the first, when it is actually a consequence. "Nevertheless" incorrectly signals concession, implying the second sentence is surprising given the first, which it is not.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FJSUVX', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Microplastics have been detected in drinking water, agricultural soil, and even remote mountain glaciers, prompting concern among environmental scientists. Some researchers argue that the health risks of microplastic ingestion remain poorly understood and may be overstated by media coverage. _______ these same researchers acknowledge that the persistence of microplastics in ecosystems warrants continued monitoring and preventive regulation.', $lyceon_json$[{"key":"A","text":"Moreover,"},{"key":"B","text":"That is,"},{"key":"C","text":"Consequently,"},{"key":"D","text":"Even so,"}]$lyceon_json$::jsonb, 'D', NULL, E'"Even so" correctly signals a concession: the researchers have just argued that health risks may be overstated, yet they still acknowledge the need for monitoring and regulation. This transition captures the shift from skepticism about the severity of the risk to agreement that precautionary measures are justified. "Moreover" incorrectly signals that the third sentence adds a supporting point in the same direction as the second, but the third sentence actually qualifies the second by introducing a contrasting acknowledgment. "That is" incorrectly signals a restatement or clarification, but the third sentence introduces a new, partially opposing point rather than rephrasing the preceding claim. "Consequently" incorrectly signals that the researchers'' call for monitoring and regulation follows as a logical result of the claim that risks are overstated, when a conclusion drawn from overstated risks would more logically be to reduce, not continue, regulatory attention.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GB7P65', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'The student wants to present the threat facing coral reefs while acknowledging a potential scientific response. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching a topic, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HQL0VK', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The marine biologist spent three years studying coral reefs in the Pacific Ocean ______ her research revealed that rising water temperatures were accelerating bleaching at an unprecedented rate.', $lyceon_json$[{"key":"A","text":"Ocean, her"},{"key":"B","text":"Ocean her"},{"key":"C","text":"Ocean. Her"},{"key":"D","text":"Ocean, which her"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice uses a period to separate two independent clauses: "The marine biologist spent three years studying coral reefs in the Pacific Ocean" and "Her research revealed that rising water temperatures were accelerating bleaching at an unprecedented rate." Using only a comma between two independent clauses creates a comma splice. Removing all punctuation produces a fused sentence. Inserting "which" after a comma creates a relative clause that lacks a grammatical role for "which" in the second clause, producing an ungrammatical construction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IXL4BP', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes a key difference between Chen''s position in Text 1 and Alvarez''s position in Text 2?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JE2IMV', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeological evidence suggests that the ancient Indus Valley civilization maintained extensive trade networks spanning from Mesopotamia to Central Asia. The uniformity of weights and measures found across Indus Valley sites indicates a high degree of administrative coordination. _______ no deciphered written records exist to confirm how this coordination was achieved, leaving historians reliant on material evidence alone to reconstruct the civilization''s governance systems.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"Furthermore,"},{"key":"C","text":"Yet"},{"key":"D","text":"For this reason,"}]$lyceon_json$::jsonb, 'C', NULL, E'"Yet" correctly signals an adversative relationship: the preceding sentences establish strong material evidence for administrative coordination, but the final sentence introduces a complicating limitation — the absence of deciphered written records that would confirm how that coordination worked. "In other words" incorrectly signals a restatement, but the final sentence does not rephrase the point about uniform weights and measures; it introduces a separate problem regarding the lack of textual evidence. "Furthermore" incorrectly signals that the final sentence adds a supporting detail in the same direction, but the absence of written records is a limitation that complicates, rather than reinforces, the preceding claims. "For this reason" incorrectly implies that the lack of deciphered records is a consequence of the uniform weights and measures, a causal connection the passage does not support.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2L9AFK9', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Marine biologists studying coral reefs in the Pacific Ocean have documented a surprising recovery in areas previously damaged by rising water temperatures. After a severe bleaching event in 2019 left large sections of reef devoid of living coral, researchers returned in 2023 to find that certain species of coral had recolonized the damaged zones. The recovery was most pronounced in areas where local fishing restrictions had been enforced, suggesting that reducing additional stressors can help reefs bounce back from thermal damage.', $lyceon_json$[{"key":"A","text":"Coral reefs damaged by high water temperatures can recover more effectively when other environmental stressors are minimized."},{"key":"B","text":"Fishing restrictions are the primary cause of coral bleaching events in the Pacific Ocean."},{"key":"C","text":"Marine biologists have concluded that all coral species are equally capable of surviving bleaching events."},{"key":"D","text":"Rising water temperatures in the Pacific Ocean have had no lasting effect on coral reef ecosystems."}]$lyceon_json$::jsonb, 'A', NULL, E'The text describes coral reef recovery following a bleaching event and emphasizes that recovery was strongest where fishing restrictions reduced additional stressors, making the choice about recovery being aided by minimizing other stressors the best statement of the main idea. The choice linking fishing restrictions to causing bleaching reverses the relationship described in the passage, since fishing restrictions helped recovery rather than caused damage. The choice claiming all species are equally capable of surviving overgeneralizes, as the passage mentions only "certain species" recolonized the damaged areas. The choice stating that rising temperatures had no lasting effect contradicts the passage, which describes severe bleaching damage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MWT9CX', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Which choice best describes the relationship between Text 2 and Text 1?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2N289QS', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Urban ecologists have observed that certain bird species thrive in cities despite the noise, light pollution, and limited green space. Studies show that house sparrows, pigeons, and starlings have adapted behaviorally to urban environments — for example, by altering their song frequencies to be heard above traffic noise. These species also benefit from the abundant food waste generated by dense human populations. In contrast, bird species that depend on large tracts of unbroken forest have declined sharply in metropolitan areas. This pattern suggests that urban environments favor bird species that ________', $lyceon_json$[{"key":"A","text":"can modify their behavior and exploit human-generated resources."},{"key":"B","text":"have evolved to avoid all contact with human populations."},{"key":"C","text":"require large territories with minimal human disturbance."},{"key":"D","text":"rely primarily on insects found in forested habitats."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes birds that succeed in cities by adjusting their behavior (altering song frequencies) and taking advantage of human food waste, so the logical completion is that urban environments favor species that can modify behavior and exploit human-generated resources. The choice about avoiding human contact contradicts the passage, which describes successful urban birds as those that live alongside humans. The choice about requiring large territories describes the forest-dependent species that have declined in cities, the opposite of what thrives. The choice about relying on insects from forested habitats introduces a food source not discussed in the passage and describes a trait of forest-dwelling birds, not urban ones.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PIK3B7', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'The student wants to emphasize Dr. Daly''s contributions to medical research. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching a topic, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QYSIZS', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'A student claims that the new scheduling policy has improved employee satisfaction at Greenfield Industries. Which quotation from the text, if true, would most directly support this claim?', E'Greenfield Industries implemented a flexible scheduling policy in January 2024, allowing employees to choose their own start and end times within a four-hour window. A company survey conducted six months later found that 82 percent of employees rated their work-life balance as "good" or "excellent," compared with 54 percent in the previous year''s survey. However, some managers reported difficulties coordinating team meetings, and productivity metrics remained essentially unchanged from the prior year.', $lyceon_json$[{"key":"A","text":"\"82 percent of employees rated their work-life balance as 'good' or 'excellent,' compared with 54 percent in the previous year's survey\""},{"key":"B","text":"\"some managers reported difficulties coordinating team meetings\""},{"key":"C","text":"\"productivity metrics remained essentially unchanged from the prior year\""},{"key":"D","text":"\"allowing employees to choose their own start and end times within a four-hour window\""}]$lyceon_json$::jsonb, 'A', NULL, E'The quotation citing the increase in positive work-life balance ratings from 54 percent to 82 percent directly supports the claim that employee satisfaction improved. The quotation about managers having difficulty coordinating meetings addresses a drawback of the policy rather than evidence of improved satisfaction. The quotation about unchanged productivity metrics is irrelevant to satisfaction, since productivity and satisfaction are distinct measures. The quotation describing the policy''s structure explains what the policy allows but does not provide evidence of its effect on satisfaction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RKQC4E', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does "tender" most nearly mean?', E'After reviewing the proposals from multiple contractors, the committee decided to accept the lowest tender for the bridge renovation, citing budget constraints as the primary factor in their decision.', $lyceon_json$[{"key":"A","text":"gentle"},{"key":"B","text":"bid"},{"key":"C","text":"painful"},{"key":"D","text":"young"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is "bid." In the context of reviewing contractor proposals, a "tender" is a formal offer submitted for a project, and the committee is selecting the least expensive one. "Gentle" is a common meaning of "tender" but produces an incoherent phrase when substituted — "the lowest gentle" is nonsensical in a procurement context. "Painful" relates to physical sensitivity or soreness, which cannot describe a contractor''s submission. "Young" refers to age and has no connection to evaluating construction proposals or their costs.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RSMM1B', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The city''s plan to convert abandoned rail lines into pedestrian greenways was initially met with skepticism from ______ after the first two-mile segment opened in 2021, property values along the corridor increased by an average of twelve percent.', $lyceon_json$[{"key":"A","text":"residents, however, after"},{"key":"B","text":"residents; however, after"},{"key":"C","text":"residents however, after"},{"key":"D","text":"residents however after"}]$lyceon_json$::jsonb, 'B', NULL, E'Two independent clauses expressing contrasting ideas must be separated by a semicolon when joined by the conjunctive adverb "however." The correct choice places a semicolon before "however" and a comma after it, which is the standard punctuation pattern for conjunctive adverbs between independent clauses. Using commas on both sides of "however" produces a comma splice, because a comma alone cannot join two independent clauses. Omitting the semicolon while keeping only the comma after "however" fuses the first clause into the conjunctive adverb without a proper boundary. Removing all punctuation around "however" creates a fused sentence and fails to set off the conjunctive adverb.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2T7M6OT', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'A literary critic argues that the narrator of the novel uses descriptions of weather to mirror the emotional states of the protagonist. Which quotation from the text would most directly support this claim?', E'Novelist Amara Dione''s 2023 work The Glass Meridian follows a young cartographer navigating personal loss while mapping an unnamed coastline. In the novel''s opening chapter, the protagonist arrives at the shore under cloudless skies, buoyed by professional ambition. As the narrative progresses and the protagonist confronts suppressed grief over her father''s death, the descriptions shift markedly: "The fog settled in layers, each one heavier than the last, until the peninsula she had been mapping disappeared entirely — not erased but simply made unreachable, the way certain memories seal themselves behind a thickness you cannot name." By the novel''s resolution, as the protagonist begins to reconcile with her grief, "thin bands of light stretched across the water, tentative as a first conversation after long silence."', $lyceon_json$[{"key":"A","text":"\"The fog settled in layers, each one heavier than the last, until the peninsula she had been mapping disappeared entirely — not erased but simply made unreachable, the way certain memories seal themselves behind a thickness you cannot name.\""},{"key":"B","text":"\"thin bands of light stretched across the water, tentative as a first conversation after long silence\""},{"key":"C","text":"The protagonist arrives at the shore under cloudless skies, buoyed by professional ambition."},{"key":"D","text":"The novel follows a young cartographer navigating personal loss while mapping an unnamed coastline."}]$lyceon_json$::jsonb, 'A', NULL, E'The quotation about fog settling in layers and making the peninsula unreachable most directly supports the critic''s claim because it explicitly links a weather description to an emotional state through the simile comparing the fog''s effect to how "certain memories seal themselves behind a thickness you cannot name." The quotation about thin bands of light does use weather to suggest emotional change, but it is less direct in its connection — the simile compares light to a conversation, not explicitly to the protagonist''s internal state, making it a weaker piece of evidence. The detail about cloudless skies and professional ambition pairs weather with mood but is a summary statement from the passage author rather than a quotation from the novel demonstrating the narrator''s technique. The description of the novel''s premise provides no weather imagery at all and therefore cannot support a claim about weather mirroring emotion.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TB4FD5', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'The student wants to explain why conservation groups are encouraging people to plant milkweed. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching a topic, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TC1N8W', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the last sentence in the text?', E'The conventional view of muscle fatigue holds that muscles fail when they exhaust their energy supplies or accumulate excessive metabolic byproducts such as lactic acid. However, recent neurophysiological research suggests a more complex picture. Studies have shown that the central nervous system may proactively reduce muscle activation before peripheral failure occurs, acting as a governor that limits exertion to protect the body from damage. Under this model, the sensation of fatigue is not a direct readout of muscular depletion but rather a constructed signal — an interpretation by the brain that may not correspond precisely to the muscles'' actual capacity.', $lyceon_json$[{"key":"A","text":"It clarifies a key implication of the alternative model described in the preceding sentences."},{"key":"B","text":"It provides experimental data that confirms the conventional view of muscle fatigue."},{"key":"C","text":"It introduces a third perspective that is distinct from both views discussed in the passage."},{"key":"D","text":"It acknowledges a limitation of the neurophysiological research mentioned earlier."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that the last sentence clarifies an implication of the alternative model. The final sentence elaborates on the central nervous system governor model by spelling out what it means for the sensation of fatigue: it is a brain-constructed signal rather than a literal measure of muscular depletion. This is a direct consequence of the model introduced in the preceding sentences. The choice about providing experimental data is wrong because the last sentence offers an interpretive restatement, not empirical results, and it supports the alternative model, not the conventional view. The choice about a third perspective mischaracterizes the sentence, which develops the already-introduced neurophysiological model rather than adding a new one. The choice about acknowledging a research limitation is inaccurate because the sentence extends the model''s explanatory reach rather than identifying weaknesses.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2U59BW1', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In a 2022 study, psychologist Elara Okonkwo examined the effect of background music on reading comprehension among college students. Participants were divided into three groups: one read in silence, another with instrumental music, and a third with lyrical music. While the silent and instrumental groups performed comparably on comprehension tests, the lyrical-music group scored significantly lower. Okonkwo proposed that the linguistic content of songs competes with the reading task for the brain''s language-processing resources, creating interference that instrumental music does not produce.', $lyceon_json$[{"key":"A","text":"Lyrical music impairs reading comprehension because its linguistic content competes with the language-processing demands of reading."},{"key":"B","text":"Instrumental music enhances reading comprehension by stimulating areas of the brain associated with focus and memory."},{"key":"C","text":"College students who listen to music while studying consistently perform worse than those who study in silence."},{"key":"D","text":"Okonkwo's study demonstrated that background noise of any kind reduces academic performance."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on Okonkwo''s finding that lyrical music specifically impaired comprehension because its linguistic content created interference with reading. The choice about instrumental music enhancing comprehension goes beyond the text, which states only that the instrumental group performed comparably to the silent group, not that instrumental music provided any benefit. The choice claiming students who listen to music consistently perform worse misrepresents the findings, since the instrumental group performed as well as the silent group. The choice about background noise of any kind reducing performance overgeneralizes the study''s conclusion, which distinguished between lyrical and instrumental music.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZG8B0S', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Historian Kenji Watanabe has studied the adoption of mechanical clocks in fourteenth-century European cities. Before clocks were installed on public buildings, daily routines were organized around natural markers such as sunrise, sunset, and church bells rung at canonical hours. Watanabe notes that the introduction of mechanical clocks did not merely provide a more precise way to track time — it fundamentally restructured labor practices. Employers began specifying exact start and end times for workers, and wages increasingly were calculated by the hour rather than by the task completed. Watanabe argues that this shift reveals how ________', $lyceon_json$[{"key":"A","text":"a new technology can reshape social and economic relationships, not just improve existing practices."},{"key":"B","text":"workers in the fourteenth century preferred hourly wages to task-based compensation."},{"key":"C","text":"mechanical clocks were less accurate than the natural time markers they replaced."},{"key":"D","text":"the primary purpose of mechanical clocks was to increase the productivity of urban workers."}]$lyceon_json$::jsonb, 'A', NULL, E'Watanabe''s argument traces how mechanical clocks did not merely improve timekeeping but restructured labor practices entirely, so the logical completion is that a new technology can reshape social and economic relationships rather than just improve existing ones. The choice about workers preferring hourly wages is unsupported; the passage describes the shift to hourly wages as employer-driven and says nothing about worker preferences. The choice about clocks being less accurate contradicts the passage, which describes clocks as providing "a more precise way to track time." The choice about the primary purpose being to increase productivity goes beyond the evidence; the passage describes consequences of clock adoption, not the intentions behind it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
